/* 解析確認題（國語匯入題庫 custom）：看完解析後再問一題，確認他真的讀懂解析。
 * 格式：id → { q: 題目, o: [4 個選項], a: 正解索引 }
 *
 * Tony 2026-08-27 定案：「認哪題的解析很沒意義，只是為了確認有沒有看，我們是希望使用者
 * 能懂解析內容，所以還是要根據解析出題比較好。」——所以這裡的每一題都是依該題解析的
 * **內容**出的，不是問「哪一句是這題的解析」。
 *
 * 硬規則（test/test.js 有守門，違反會測試失敗）：
 *   · 答案只能在該題自己的解析裡找得到；正解的關鍵詞必須真的出現在該題 exp 中
 *   · 恰 4 個選項且不重複；answer 索引有效
 *   · 誘答要似是而非，禁用「以上皆非」「都不對」這種湊數選項
 *   · 不可寫位置指涉（「第一句」「最後一個選項」）——解析與選項的順序會變
 *   · 逐題人工撰寫（不可交 subagent 量產，2026-08-02 四個 agent 全交假貨）
 */
